{"type":"tool_call","toolCallId":"call-1bb0b85b-be44-4461-ae0d-7ccc35fb2b8f-7","title":"write","kind":"write","status":"pending","toolName":"write","rawInput":{"file_path":"/private/var/folders/_l/4gzjzznn2z73r8kldgtyxsmw0000gn/T/jonny-bench-work-VHXGAl/src/style.css","content":":root {
  --bg: #07090f;
  --panel: rgba(10, 14, 24, 0.88);
  --line: rgba(120, 180, 255, 0.22);
  --text: #e8eefc;
  --muted: #8b9bb8;
  --accent: #4de1ff;
  --hot: #ff6b2c;
  --gold: #ffd166;
  --good: #5dffb1;
  --bad: #ff4d6d;
  --font: "Segoe UI", system-ui, -apple-system, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
}

html, body, #app {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
}

#ui {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
}

#ui .interactive {
  pointer-events: auto;
}

/* HUD */
.hud {
  position: absolute;
  inset: 0;
  padding: 16px 18px;
  display: none;
}

.hud.visible {
  display: block;
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.stat-block {
  min-width: 180px;
}

.stat-label {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 6px;
}

.bar {
  height: 12px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--line);
  border-radius: 999px;
  overflow: hidden;
  position: relative;
}

.bar > i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  transform: scaleX(1);
  border-radius: inherit;
  transition: transform 0.12s ease-out;
}

.bar.hp > i {
  background: linear-gradient(90deg, #ff4d6d, #ff8f6b);
  box-shadow: 0 0 12px rgba(255, 77, 109, 0.55);
}

.bar.heat > i {
  background: linear-gradient(90deg, #4de1ff, #ff6b2c);
  box-shadow: 0 0 12px rgba(77, 225, 255, 0.4);
}

.bar-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}

.hud-right {
  text-align: right;
}

.room-title {
  font-size: 13px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 0 0 18px rgba(77, 225, 255, 0.5);
}

.room-sub {
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}

.kill-feed {
  position: absolute;
  top: 88px;
  right: 18px;
  text-align: right;
  font-size: 12px;
  color: var(--gold);
  opacity: 0.9;
}

.combo {
  position: absolute;
  left: 50%;
  top: 18%;
  transform: translateX(-50%);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--gold);
  text-shadow: 0 0 24px rgba(255, 209, 102, 0.7);
  opacity: 0;
  transition: opacity 0.15s ease;
  pointer-events: none;
}

.combo.show {
  opacity: 1;
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 22%;
  transform: translateX(-50%);
  padding: 10px 16px;
  border-radius: 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  color: var(--text);
  font-size: 14px;
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: none;
  white-space: nowrap;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(-6px);
}

.hint-bar {
  position: absolute;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.04em;
  text-align: center;
  background: rgba(7, 9, 15, 0.55);
  border: 1px solid rgba(120, 180, 255, 0.12);
  border-radius: 999px;
  padding: 8px 14px;
}

.hint-bar kbd {
  display: inline-block;
  padding: 1px 6px;
  margin: 0 2px;
  border-radius: 4px;
  border: 1px solid rgba(120, 180, 255, 0.28);
  background: rgba(255, 255, 255, 0.04);
  color: var(--accent);
  font-size: 11px;
  font-family: inherit;
}

/* Screens */
.screen {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 20%, rgba(77, 225, 255, 0.12), transparent 50%),
    radial-gradient(ellipse at 70% 80%, rgba(255, 107, 44, 0.1), transparent 45%),
    rgba(7, 9, 15, 0.72);
  pointer-events: auto;
  padding: 24px;
}

.screen.visible {
  display: flex;
}

.panel {
  width: min(720px, 100%);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 28px 28px 24px;
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.02) inset,
    0 30px 80px rgba(0, 0, 0, 0.45),
    0 0 60px rgba(77, 225, 255, 0.08);
  backdrop-filter: blur(12px);
}

.logo {
  font-size: clamp(36px, 7vw, 56px);
  font-weight: 800;
  letter-spacing: 0.18em;
  text-align: center;
  background: linear-gradient(120deg, #4de1ff 0%, #fff3a0 45%, #ff6b2c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: none;
  filter: drop-shadow(0 0 24px rgba(77, 225, 255, 0.35));
}

.tagline {
  text-align: center;
  color: var(--muted);
  margin-top: 8px;
  margin-bottom: 22px;
  font-size: 14px;
  letter-spacing: 0.06em;
}

.blurb {
  color: var(--text);
  line-height: 1.55;
  font-size: 14px;
  margin-bottom: 18px;
  opacity: 0.92;
}

.controls-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 16px;
  margin-bottom: 22px;
  font-size: 13px;
  color: var(--muted);
}

.controls-grid strong {
  color: var(--accent);
  font-weight: 600;
}

.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

button.btn {
  appearance: none;
  border: 1px solid rgba(77, 225, 255, 0.35);
  background: linear-gradient(180deg, rgba(77, 225, 255, 0.16), rgba(77, 225, 255, 0.05));
  color: var(--text);
  font: inherit;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 13px;
  padding: 12px 22px;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease, border-color 0.12s ease;
  box-shadow: 0 0 20px rgba(77, 225, 255, 0.12);
}

button.btn:hover {
  transform: translateY(-1px);
  border-color: rgba(77, 225, 255, 0.7);
  box-shadow: 0 0 28px rgba(77, 225, 255, 0.28);
}

button.btn:active {
  transform: translateY(1px);
}

button.btn.hot {
  border-color: rgba(255, 107, 44, 0.5);
  background: linear-gradient(180deg, rgba(255, 107, 44, 0.22), rgba(255, 107, 44, 0.06));
  box-shadow: 0 0 20px rgba(255, 107, 44, 0.15);
}

button.btn.hot:hover {
  border-color: rgba(255, 107, 44, 0.85);
  box-shadow: 0 0 28px rgba(255, 107, 44, 0.3);
}

button.btn.ghost {
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.03);
  box-shadow: none;
}

.stats-line {
  margin-top: 16px;
  text-align: center;
  font-size: 12px;
  color: var(--muted);
}

/* Upgrade draft */
.upgrade-screen .panel {
  width: min(920px, 100%);
}

.upgrade-title {
  text-align: center;
  font-size: 22px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 6px;
  color: var(--gold);
}

.upgrade-sub {
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  margin-bottom: 20px;
}

.upgrade-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

@media (max-width: 720px) {
  .upgrade-cards {
    grid-template-columns: 1fr;
  }
  .controls-grid {
    grid-template-columns: 1fr;
  }
}

.card {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 16px;
  background: rgba(255, 255, 255, 0.03);
  cursor: pointer;
  transition: transform 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease;
  text-align: left;
  color: inherit;
  font: inherit;
  min-height: 160px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card:hover {
  transform: translateY(-3px);
  border-color: rgba(77, 225, 255, 0.55);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), 0 0 24px rgba(77, 225, 255, 0.12);
}

.card.rarity-common { border-top: 3px solid #8b9bb8; }
.card.rarity-rare { border-top: 3px solid #4de1ff; }
.card.rarity-epic { border-top: 3px solid #c084fc; }
.card.rarity-legendary { border-top: 3px solid #ffd166; }

.card-rarity {
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.card-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
}

.card-desc {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.45;
  flex: 1;
}

.paused-badge {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 42px;
  letter-spacing: 0.3em;
  color: rgba(255, 255, 255, 0.35);
  display: none;
  pointer-events: none;
}

.paused-badge.show {
  display: block;
}

.damage-flash {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, transparent 40%, rgba(255, 40, 70, 0.28));
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.08s linear;
}

.damage-flash.show {
  opacity: 1;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(0, 0, 0, 0.45) 100%);
}

.run-mods {
  margin-top: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
}

.mod-chip {
  font-size: 11px;
  padding: 4px 8px;
  border-radius: 999px;
  border: 1px solid rgba(120, 180, 255, 0.2);
  color: var(--muted);
  background: rgba(255, 255, 255, 0.03);
}
"},"content":[],"locations":[]}

