  letter-spacing: -0.24px;
  margin: 0 0 8px;
  @media (max-width: 1024px) {
    font-size: 20px;
  }
}
p {
  margin: 0;
}

code,
.counter {
  font-family: var(--mono);
  display: inline-flex;
  border-radius: 4px;
  color: var(--text-h);
}

code {
  font-size: 15px;
  line-height: 135%;
  padding: 4px 8px;
  background: var(--code-bg);
}

.counter {
  font-size: 16px;
  padding: 5px 10px;
  border-radius: 5px;
  color: var(--accent);
  background: var(--accent-bg);
  border: 2px solid transparent;
  transition: border-color 0.3s;
  margin-bottom: 24px;

  &:hover {
    border-color: var(--accent-border);
  }
  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

.hero {
  position: relative;

  .base,
  .framework,
  .vite {
    inset-inline: 0;
    margin: 0 auto;
  }

  .base {
    width: 170px;
    position: relative;
    z-index: 0;
  }

  .framework,
  .vite {
    position: absolute;
  }

  .framework {
    z-index: 1;
    top: 34px;
    height: 28px;
    transform: perspective(2000px) rotateZ(300deg) rotateX(44deg) rotateY(39deg)
      scale(1.4);
  }

  .vite {
    z-index: 0;
    top: 107px;
    height: 26px;
    width: auto;
    transform: perspective(2000px) rotateZ(300deg) rotateX(40deg) rotateY(39deg)
      scale(0.8);
  }
}

#app {
  width: 1126px;
  max-width: 100%;
  margin: 0 auto;
  text-align: center;
  border-inline: 1px solid var(--border);
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

#center {
  display: flex;
  flex-direction: column;
  gap: 25px;
  place-content: center;
  place-items: center;
  flex-grow: 1;

  @media (max-width: 1024px) {
    padding: 32px 20px 24px;
    gap: 18px;
  }
}

#next-steps {
  display: flex;
  border-top: 1px solid var(--border);
  text-align: left;

  & > div {
    flex: 1 1 0;
    padding: 32px;
    @media (max-width: 1024px) {
      padding: 24px 20px;
    }
  }

  .icon {
    margin-bottom: 16px;
    width: 22px;
    height: 22px;
  }

  @media (max-width: 1024px) {
    flex-direction: column;
    text-align: center;
  }
}

#docs {
  border-right: 1px solid var(--border);

  @media (max-width: 1024px) {
    border-right: none;
    border-bottom: 1px solid var(--border);
  }
}

#next-steps ul {
  list-style: none;
  padding: 0;
  display: flex;
  gap: 8px;
  margin: 32px 0 0;

  .logo {
    height: 18px;
  }

  a {
    color: var(--text-h);
    font-size: 16px;
    border-radius: 6px;
    background: var(--social-bg);
    display: flex;
    padding: 6px 12px;
    align-items: center;
    gap: 8px;
    text-decoration: none;
    transition: box-shadow 0.3s;

    &:hover {
      box-shadow: var(--shadow);
    }
    .button-icon {
      height: 18px;
      width: 18px;
    }
  }

  @media (max-width: 1024px) {
    margin-top: 20px;
    flex-wrap: wrap;
    justify-content: center;

    li {
      flex: 1 1 calc(50% - 8px);
    }

    a {
      width: 100%;
      justify-content: center;
      box-sizing: border-box;
    }
  }
}

#spacer {
  height: 88px;
  border-top: 1px solid var(--border);
  @media (max-width: 1024px) {
    height: 48px;
  }
}

.ticks {
  position: relative;
  width: 100%;

  &::before,
  &::after {
    content: '';
    position: absolute;
    top: -4.5px;
    border: 5px solid transparent;
  }

  &::before {
    left: 0;
    border-left-color: var(--border);
  }
  &::after {
    right: 0;
    border-right-color: var(--border);
  }
}
","newText":":root {
  --bg: #07090f;
  --panel: rgba(10, 14, 24, 0.88);
  --line: rgba(120, 180, 255, 0.22);
  --text: #e8eefc;
  --muted: #8b9bb8;
  --accent: #4de1ff;
  --hot: #ff6b2c;
  --gold: #ffd166;
  --good: #5dffb1;
  --bad: #ff4d6d;
  --font: "Segoe UI", system-ui, -apple-system, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
}

html, body, #app {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
}

#ui {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
}

#ui .interactive {
  pointer-events: auto;
}

/* HUD */
.hud {
  position: absolute;
  inset: 0;
  padding: 16px 18px;
  display: none;
}

.hud.visible {
  display: block;
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.stat-block {
  min-width: 180px;
}

.stat-label {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 6px;
}

.bar {
  height: 12px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--line);
  border-radius: 999px;
  overflow: hidden;
  position: relative;
}

.bar > i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  transform: scaleX(1);
  border-radius: inherit;
  transition: transform 0.12s ease-out;
}

.bar.hp > i {
  background: linear-gradient(90deg, #ff4d6d, #ff8f6b);
  box-shadow: 0 0 12px rgba(255, 77, 109, 0.55);
}

.bar.heat > i {
  background: linear-gradient(90deg, #4de1ff, #ff6b2c);
  box-shadow: 0 0 12px rgba(77, 225, 255, 0.4);
}

.bar-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}

.hud-right {
  text-align: right;
}

.room-title {
  font-size: 13px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 0 0 18px rgba(77, 225, 255, 0.5);
}

.room-sub {
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}

.kill-feed {
  position: absolute;
  top: 88px;
  right: 18px;
  text-align: right;
  font-size: 12px;
  color: var(--gold);
  opacity: 0.9;
}

.combo {
  position: absolute;
  left: 50%;
  top: 18%;
  transform: translateX(-50%);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--gold);
  text-shadow: 0 0 24px rgba(255, 209, 102, 0.7);
  opacity: 0;
  transition: opacity 0.15s ease;
  pointer-events: none;
}

.combo.show {
  opacity: 1;
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 22%;
  transform: translateX(-50%);
  padding: 10px 16px;
  border-radius: 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  color: var(--text);
  font-size: 14px;
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: none;
  white-space: nowrap;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(-6px);
}

.hint-bar {
  position: absolute;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.04em;
  text-align: center;
  background: rgba(7, 9, 15, 0.55);
  border: 1px solid rgba(120, 180, 255, 0.12);
  border-radius: 999px;
  padding: 8px 14px;
}

.hint-bar kbd {
  display: inline-block;
  padding: 1px 6px;
  margin: 0 2px;
  border-radius: 4px;
  border: 1px solid rgba(120, 180, 255, 0.28);
  background: rgba(255, 255, 255, 0.04);
  color: var(--accent);
  font-size: 11px;
  font-family: inherit;
}

/* Screens */
.screen {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 20%, rgba(77, 225, 255, 0.12), transparent 50%),
    radial-gradient(ellipse at 70% 80%, rgba(255, 107, 44, 0.1), transparent 45%),
    rgba(7, 9, 15, 0.72);
  pointer-events: auto;
  padding: 24px;
}

.screen.visible {
  display: flex;
}

.panel {
  width: min(720px, 100%);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 28px 28px 24px;
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.02) inset,
    0 30px 80px rgba(0, 0, 0, 0.45),
    0 0 60px rgba(77, 225, 255, 0.08);
  backdrop-filter: blur(12px);
}

.logo {
  font-size: clamp(36px, 7vw, 56px);
  font-weight: 800;
  letter-spacing: 0.18em;
  text-align: center;
  background: linear-gradient(120deg, #4de1ff 0%, #fff3a0 45%, #ff6b2c 100%);
  -webkit-background-clip: text;
  background-clip: text;
