","new_string":":root {
  --bg: #07090f;
  --panel: rgba(10, 14, 24, 0.88);
  --line: rgba(120, 180, 255, 0.22);
  --text: #e8eefc;
  --muted: #8b9bb8;
  --accent: #4de1ff;
  --hot: #ff6b2c;
  --gold: #ffd166;
  --good: #5dffb1;
  --bad: #ff4d6d;
  --font: "Segoe UI", system-ui, -apple-system, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
}

html, body, #app {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
}

#ui {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
}

#ui .interactive {
  pointer-events: auto;
}

/* HUD */
.hud {
  position: absolute;
  inset: 0;
  padding: 16px 18px;
  display: none;
}

.hud.visible {
  display: block;
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.stat-block {
  min-width: 180px;
}

.stat-label {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 6px;
}

.bar {
  height: 12px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--line);
  border-radius: 999px;
  overflow: hidden;
  position: relative;
}

.bar > i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  transform: scaleX(1);
  border-radius: inherit;
  transition: transform 0.12s ease-out;
}

.bar.hp > i {
  background: linear-gradient(90deg, #ff4d6d, #ff8f6b);
  box-shadow: 0 0 12px rgba(255, 77, 109, 0.55);
}

.bar.heat > i {
  background: linear-gradient(90deg, #4de1ff, #ff6b2c);
  box-shadow: 0 0 12px rgba(77, 225, 255, 0.4);
}

.bar-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}

.hud-right {
  text-align: right;
}

.room-title {
  font-size: 13px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 0 0 18px rgba(77, 225, 255, 0.5);
}

.room-sub {
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}

.kill-feed {
  position: absolute;
  top: 88px;
  right: 18px;
  text-align: right;
  font-size: 12px;
  color: var(--gold);
  opacity: 0.9;
}

.combo {
  position: absolute;
  left: 50%;
  top: 18%;
  transform: translateX(-50%);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--gold);
  text-shadow: 0 0 24px rgba(255, 209, 102, 0.7);
  opacity: 0;
  transition: opacity 0.15s ease;
  pointer-events: none;
}

.combo.show {
  opacity: 1;
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 22%;
  transform: translateX(-50%);
  padding: 10px 16px;
  border-radius: 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  color: var(--text);
  font-size: 14px;
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: none;
  white-space: nowrap;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(-6px);
}

.hint-bar {
  position: absolute;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.04em;
  text-align: center;
  background: rgba(7, 9, 15, 0.55);
  border: 1px solid rgba(120, 180, 255, 0.12);
  border-radius: 999px;
  padding: 8px 14px;
}

.hint-bar kbd {
  display: inline-block;
  padding: 1px 6px;
  margin: 0 2px;
  border-radius: 4px;
  border: 1px solid rgba(120, 180, 255, 0.28);
  background: rgba(255, 255, 255, 0.04);
  color: var(--accent);
  font-size: 11px;
  font-family: inherit;
}

