.screen {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 20%, rgba(77, 225, 255, 0.12), transparent 50%),
    radial-gradient(ellipse at 70% 80%, rgba(255, 107, 44, 0.1), transparent 45%),
    rgba(7, 9, 15, 0.72);
  pointer-events: auto;
  padding: 24px;
}

.screen.visible {
  display: flex;
}

.panel {
  width: min(720px, 100%);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 28px 28px 24px;
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.02) inset,
    0 30px 80px rgba(0, 0, 0, 0.45),
    0 0 60px rgba(77, 225, 255, 0.08);
  backdrop-filter: blur(12px);
}

.logo {
  font-size: clamp(36px, 7vw, 56px);
  font-weight: 800;
  letter-spacing: 0.18em;
  text-align: center;
  background: linear-gradient(120deg, #4de1ff 0%, #fff3a0 45%, #ff6b2c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: none;
  filter: drop-shadow(0 0 24px rgba(77, 225, 255, 0.35));
}

.tagline {
  text-align: center;
  color: var(--muted);
  margin-top: 8px;
  margin-bottom: 22px;
  font-size: 14px;
  letter-spacing: 0.06em;
}

.blurb {
  color: var(--text);
  line-height: 1.55;
  font-size: 14px;
  margin-bottom: 18px;
  opacity: 0.92;
}

.controls-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 16px;
  margin-bottom: 22px;
  font-size: 13px;
  color: var(--muted);
}

.controls-grid strong {
  color: var(--accent);
  font-weight: 600;
}

.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

button.btn {
  appearance: none;
  border: 1px solid rgba(77, 225, 255, 0.35);
  background: linear-gradient(180deg, rgba(77, 225, 255, 0.16), rgba(77, 225, 255, 0.05));
