  box-shadow: 0 0 28px rgba(77, 225, 255, 0.28);
}

button.btn:active {
  transform: translateY(1px);
}

button.btn.hot {
  border-color: rgba(255, 107, 44, 0.5);
  background: linear-gradient(180deg, rgba(255, 107, 44, 0.22), rgba(255, 107, 44, 0.06));
