}

.upgrade-sub {
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  margin-bottom: 20px;
}

.upgrade-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

