export function pickUpgrades(count, rng, ownedIds = new Set()) {
  const pool = UPGRADES.filter((u) => !ownedIds.has(u.id) || u.rarity === 'common');
  const picks = [];
  const used = new Set();

  for (let n = 0; n < count; n++) {
    let total = 0;
    const weights = [];
    for (const u of pool) {
      if (used.has(u.id)) {
        weights.push(0);
        continue;
      }
      const w = RARITY_WEIGHT[u.rarity] || 10;
      weights.push(w);
      total += w;
    }
    if (total <= 0) break;
    let roll = rng() * total;
    let chosen = null;
    for (let i = 0; i < pool.length; i++) {
      roll -= weights[i];
      if (roll <= 0) {
        chosen = pool[i];
        break;
      }
    }
    if (!chosen) chosen = pool.find((_, i) => weights[i] > 0);
    if (!chosen) break;
    used.add(chosen.id);
    picks.push(chosen);
  }
  return picks;
}

