export class AudioBus {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this._warmed = false;
  }

  ensure() {
    if (!this.enabled) return null;
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.22;
      this.master.connect(this.ctx.destination);
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
    return this.ctx;
  }

  warm() {
    if (this._warmed) return;
    this._warmed = true;
    this.ensure();
  }

  tone({
    freq = 440,
    freqEnd = null,
    type = 'sine',
    dur = 0.12,
    gain = 0.2,
    attack = 0.005,
    decay = 0.08,
    filterFreq = null,
  } = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (freqEnd != null) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), t + dur);
    }

    let node = osc;
    if (filterFreq) {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = filterFreq;
      osc.connect(f);
      node = f;
    }

    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + Math.max(attack + 0.01, dur));

    node.connect(g);
    g.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise({ dur = 0.08, gain = 0.12, filterFreq = 1200 } = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const t = ctx.currentTime;
    const len = Math.max(1, Math.floor(ctx.sampleRate * dur));
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = filterFreq;
    f.Q.value = 0.7;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f);
    f.connect(g);
    g.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  throwTip() {
    this.tone({ freq: 520, freqEnd: 180, type: 'triangle', dur: 0.1, gain: 0.12 });
    this.noise({ dur: 0.05, gain: 0.05, filterFreq: 2000 });
  }

  latch() {
    this.tone({ freq: 140, freqEnd: 320, type: 'sawtooth', dur: 0.12, gain: 0.1, filterFreq: 900 });
  }

  hit(heavy = false) {
    this.tone({
      freq: heavy ? 90 : 180,
      freqEnd: 50,
      type: 'square',
      dur: heavy ? 0.14 : 0.07,
      gain: heavy ? 0.14 : 0.08,
      filterFreq: 700,
    });
    this.noise({ dur: 0.05, gain: heavy ? 0.1 : 0.05, filterFreq: heavy ? 600 : 1400 });
  }

  kill() {
    this.tone({ freq: 240, freqEnd: 80, type: 'sawtooth', dur: 0.18, gain: 0.12, filterFreq: 800 });
    this.tone({ freq: 480, freqEnd: 120, type: 'triangle', dur: 0.2, gain: 0.08 });
  }

  dash() {
    this.noise({ dur: 0.08, gain: 0.08, filterFreq: 900 });
    this.tone({ freq: 300, freqEnd: 90, type: 'sine', dur: 0.1, gain: 0.08 });
  }

  pulse() {
    this.tone({ freq: 70, freqEnd: 40, type: 'sine', dur: 0.28, gain: 0.18 });
    this.noise({ dur: 0.2, gain: 0.12, filterFreq: 400 });
    this.tone({ freq: 220, freqEnd: 60, type: 'triangle', dur: 0.22, gain: 0.1 });
  }

  hurt() {
    this.tone({ freq: 160, freqEnd: 50, type: 'sawtooth', dur: 0.2, gain: 0.12, filterFreq: 500 });
  }

  pickup() {
    this.tone({ freq: 520, freqEnd: 880, type: 'sine', dur: 0.12, gain: 0.1 });
    this.tone({ freq: 780, freqEnd: 1200, type: 'triangle', dur: 0.14, gain: 0.06 });
  }

  upgrade() {
    this.tone({ freq: 330, freqEnd: 660, type: 'triangle', dur: 0.18, gain: 0.1 });
    this.tone({ freq: 495, freqEnd: 990, type: 'sine', dur: 0.22, gain: 0.08 });
  }

  portal() {
    this.tone({ freq: 180, freqEnd: 360, type: 'sine', dur: 0.35, gain: 0.1 });
    this.tone({ freq: 270, freqEnd: 540, type: 'triangle', dur: 0.4, gain: 0.07 });
  }

  ui() {
    this.tone({ freq: 640, type: 'sine', dur: 0.05, gain: 0.05 });
  }

  win() {
    [440, 554, 659, 880].forEach((f, i) => {
      setTimeout(() => this.tone({ freq: f, type: 'triangle', dur: 0.25, gain: 0.1 }), i * 90);
    });
  }

  lose() {
    this.tone({ freq: 220, freqEnd: 60, type: 'sawtooth', dur: 0.5, gain: 0.12, filterFreq: 600 });
  }
}
