const _v = new THREE.Vector3();

export class ParticleSystem {
  constructor(scene, max = 900) {
    this.scene = scene;
    this.max = max;
    this.count = 0;

    this.positions = new Float32Array(max * 3);
    this.velocities = new Float32Array(max * 3);
    this.colors = new Float32Array(max * 3);
    this.life = new Float32Array(max);
    this.maxLife = new Float32Array(max);
    this.size = new Float32Array(max);

    this.geom = new THREE.BufferGeometry();
    this.geom.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    this.geom.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    this.geom.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    this.geom.setDrawRange(0, 0);

    this.mat = new THREE.PointsMaterial({
      size: 0.18,
      vertexColors: true,
      transparent: true,
      opacity: 0.9,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    });

    this.points = new THREE.Points(this.geom, this.mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
  }

  spawn(x, y, z, opts = {}) {
    if (this.count >= this.max) {
      // recycle oldest slot
      this._write(0, x, y, z, opts);
      return;
    }
    this._write(this.count, x, y, z, opts);
    this.count++;
    this.geom.setDrawRange(0, this.count);
  }

  _write(i, x, y, z, opts) {
    const speed = opts.speed ?? 4;
    const spread = opts.spread ?? 1;
    const life = opts.life ?? 0.45;
    const size = opts.size ?? 0.18;
    const color = opts.color || { r: 0.3, g: 0.9, b: 1 };

    const vx = (opts.vx ?? (Math.random() - 0.5) * spread) * speed;
    const vy = (opts.vy ?? Math.random() * spread) * speed;
    const vz = (opts.vz ?? (Math.random() - 0.5) * spread) * speed;

    const i3 = i * 3;
    this.positions[i3] = x;
    this.positions[i3 + 1] = y;
    this.positions[i3 + 2] = z;
    this.velocities[i3] = vx;
    this.velocities[i3 + 1] = vy;
    this.velocities[i3 + 2] = vz;
    this.colors[i3] = color.r;
    this.colors[i3 + 1] = color.g;
    this.colors[i3 + 2] = color.b;
    this.life[i] = life;
    this.maxLife[i] = life;
    this.size[i] = size;
  }

  burst(x, y, z, n, opts = {}) {
    for (let i = 0; i < n; i++) this.spawn(x, y, z, opts);
  }

  ring(x, y, z, n, radius, opts = {}) {
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      this.spawn(x + Math.cos(a) * radius * 0.2, y, z + Math.sin(a) * radius * 0.2, {
        ...opts,
        vx: Math.cos(a),
        vy: 0.2,
        vz: Math.sin(a),
        speed: opts.speed ?? 8,
        spread: 1,
      });
    }
  }

  update(dt) {
    let w = 0;
    for (let i = 0; i < this.count; i++) {
      this.life[i] -= dt;
      if (this.life[i] <= 0) continue;
      const i3 = i * 3;
      const w3 = w * 3;
      this.velocities[i3 + 1] -= 2.5 * dt;
      this.positions[i3] += this.velocities[i3] * dt;
      this.positions[i3 + 1] += this.velocities[i3 + 1] * dt;
      this.positions[i3 + 2] += this.velocities[i3 + 2] * dt;

      if (w !== i) {
        this.positions[w3] = this.positions[i3];
        this.positions[w3 + 1] = this.positions[i3 + 1];
        this.positions[w3 + 2] = this.positions[i3 + 2];
        this.velocities[w3] = this.velocities[i3];
        this.velocities[w3 + 1] = this.velocities[i3 + 1];
        this.velocities[w3 + 2] = this.velocities[i3 + 2];
        this.colors[w3] = this.colors[i3];
        this.colors[w3 + 1] = this.colors[i3 + 1];
        this.colors[w3 + 2] = this.colors[i3 + 2];
        this.life[w] = this.life[i];
        this.maxLife[w] = this.maxLife[i];
        this.size[w] = this.size[i];
      }
      // fade color by life
      const t = this.life[w] / this.maxLife[w];
      this.colors[w3] *= 0.98 + 0.02 * t;
      this.colors[w3 + 1] *= 0.98 + 0.02 * t;
      this.colors[w3 + 2] *= 0.98 + 0.02 * t;
      w++;
    }
    this.count = w;
    this.geom.setDrawRange(0, this.count);
    this.geom.attributes.position.needsUpdate = true;
    this.geom.attributes.color.needsUpdate = true;
  }

  clear() {
    this.count = 0;
    this.geom.setDrawRange(0, 0);
  }
}

