      chip.className = 'mod-chip';
      chip.textContent = up.name;
      this.els.runMods.appendChild(chip);
    }
    this.onState('upgrade');
  }

  showEnd(won, run, best, stats) {
    this.els.endLogo.textContent = won ? 'REACTOR QUIET' : 'CORE RUPTURE';
    this.els.endTag.textContent = won ? 'All three depths stilled' : 'The generator-city consumes you';
    this.els.endBlurb.innerHTML = `
      Scrap <strong>${run.score}</strong> · Kills <strong>${run.kills}</strong> · Depth <strong>${run.floor}</strong><br/>
      Time ${formatTime(run.time)} · Mutations ${stats.owned.length}
    `;
    this.els.endBest.textContent = `Best scrap: ${best}`;
    this.onState(won ? 'win' : 'dead');
  }
}

function clamp01(v) {
