    }
    this.obstacles.length = 0;
    if (this.portal) {
      this.scene.remove(this.portal.mesh);
      this.portal = null;
    }
    this.particles.clear();
  }

  _disposeEnemy(e) {
    this.scene.remove(e.mesh);
    e.mesh.traverse((c) => {
      if (c.geometry) c.geometry.dispose();
    });
  }

  _resetTether() {
    const t = this.tetherLine;
    t.state = 'idle';
    t.tipPos.copy(this.player.pos);
    t.tipVel.set(0, 0, 0);
    t.latchTarget = null;
    t.latchKind = null;
    t.bouncesLeft = 0;
    t.throwAge = 0;
    t.spinAngle = 0;
    t.damageCd.clear();
    t.twin = null;
    t.tip.visible = true;
    this.twinVisual.tip.visible = false;
  }

  _beginRoom(first = false) {
    this.run.room += 1;
    this.run.awaitingPortal = false;
    this.run.isBoss = false;
    this._clearEntities();
    this._resetTether();
    this.player.pos.set(0, 0.5, 0);
    this.player.vel.set(0, 0, 0);

    const floor = this.run.floor;
    const roomIdx = this.run.room;
    const isBoss = roomIdx > this.run.roomsThisFloor;
    this.run.isBoss = isBoss;

    // Room scale grows slightly
    const half = isBoss ? 16 : 12 + Math.min(4, floor);
    this._createFloor(half);

    // Obstacles
    const obsCount = isBoss ? 2 : 2 + floor + (this.rng() < 0.5 ? 1 : 0);
    for (let i = 0; i < obsCount; i++) {
      this._spawnObstacle();
    }

    if (isBoss) {
      this._spawnEnemy('boss', 0, -4);
      // adds
      const adds = 2 + floor;
      for (let i = 0; i < adds; i++) {
        const a = (i / adds) * Math.PI * 2;
        const r = 8;
        this._spawnEnemy(this.rng() < 0.5 ? 'spitter' : 'mite', Math.cos(a) * r, Math.sin(a) * r);
      }
      this.ui.toast('DYNAMO HEART ONLINE');
      this.audio.portal();
    } else {
      this._spawnWave(floor, roomIdx);
    }

    this.ui.updateRoom(this.run, isBoss);
    if (!first) this.audio.ui();
  }

  _spawnObstacle() {
    const half = this.roomBounds.half - 3;
    let x = rand(this.rng, -half, half);
    let z = rand(this.rng, -half, half);
    // keep center clear
    if (Math.hypot(x, z) < 3) {
      x += 4 * randSign(this.rng);
      z += 4 * randSign(this.rng);
    }
    const kind = this.rng();
    let mesh;
    let radius;
    if (kind < 0.55) {
      const h = rand(this.rng, 1.2, 2.4);
      const r = rand(this.rng, 0.55, 1.1);
      mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(r, r * 1.1, h, 8),
        new THREE.MeshStandardMaterial({
          color: 0x1a2740,
          emissive: 0x102030,
          metalness: 0.5,
          roughness: 0.45,
        }),
      );
      mesh.position.set(x, h / 2, z);
      radius = r + 0.1;
    } else {
      const s = rand(this.rng, 1.0, 1.8);
      mesh = new THREE.Mesh(
        new THREE.BoxGeometry(s, s, s),
        new THREE.MeshStandardMaterial({
          color: 0x182338,
          emissive: 0x0c1828,
          metalness: 0.55,
          roughness: 0.4,
        }),
      );
      mesh.position.set(x, s / 2, z);
      mesh.rotation.y = this.rng() * Math.PI;
      radius = s * 0.65;
    }
    this.roomGroup.add(mesh);
    this.obstacles.push({ mesh, x, z, radius, solid: true });
  }

  _spawnWave(floor, roomIdx) {
    const budget = 3 + roomIdx + floor * 2;
    const types = ['mite', 'mite', 'spitter', 'flicker', 'orbiter', 'bulwark'];
    // unlock types by floor
    let pool = types.slice(0, Math.min(types.length, 2 + floor));
    if (floor >= 2) pool = types.slice(0, 5);
    if (floor >= 3) pool = types;

    let spent = 0;
    const half = this.roomBounds.half - 2.5;
    while (spent < budget) {
      const type = pool[(this.rng() * pool.length) | 0];
      const cost = type === 'bulwark' ? 2.5 : type === 'spitter' ? 1.5 : 1;
      if (spent + cost > budget + 1) break;
      spent += cost;
      // spawn near edges
      const edge = (this.rng() * 4) | 0;
      let x, z;
      if (edge === 0) {
        x = rand(this.rng, -half, half);
        z = -half;
      } else if (edge === 1) {
        x = rand(this.rng, -half, half);
        z = half;
      } else if (edge === 2) {
        x = -half;
        z = rand(this.rng, -half, half);
      } else {
        x = half;
        z = rand(this.rng, -half, half);
      }
      this._spawnEnemy(type, x, z);
    }
  }

  _spawnEnemy(typeKey, x, z) {
    const def = ENEMY_TYPES[typeKey];
    const scale = 1 + (this.run.floor - 1) * 0.12;
    const group = new THREE.Group();

    let body;
    if (typeKey === 'boss') {
      body = new THREE.Mesh(
        new THREE.IcosahedronGeometry(1.2, 1),
        new THREE.MeshStandardMaterial({
          color: def.color,
          emissive: def.color,
          emissiveIntensity: 0.55,
          metalness: 0.35,
          roughness: 0.3,
        }),
      );
      const halo = new THREE.Mesh(
        new THREE.TorusGeometry(1.6, 0.08, 8, 40),
        new THREE.MeshStandardMaterial({
          color: 0x4de1ff,
          emissive: 0x4de1ff,
          emissiveIntensity: 0.8,
        }),
      );
      halo.rotation.x = Math.PI / 2;
      group.add(body, halo);
      group.userData.halo = halo;
    } else if (typeKey === 'bulwark') {
      body = new THREE.Mesh(
        new THREE.BoxGeometry(1.2, 1.3, 1.2),
        new THREE.MeshStandardMaterial({
          color: def.color,
          emissive: 0x102040,
          emissiveIntensity: 0.4,
          metalness: 0.6,
          roughness: 0.35,
        }),
      );
      group.add(body);
    } else if (typeKey === 'spitter') {
      body = new THREE.Mesh(
        new THREE.ConeGeometry(0.45, 0.9, 6),
        new THREE.MeshStandardMaterial({
          color: def.color,
          emissive: def.color,
          emissiveIntensity: 0.35,
        }),
      );
      body.rotation.x = Math.PI;
      group.add(body);
    } else if (typeKey === 'orbiter') {
      body = new THREE.Mesh(
        new THREE.TorusKnotGeometry(0.28, 0.1, 48, 8),
        new THREE.MeshStandardMaterial({
          color: def.color,
          emissive: def.color,
          emissiveIntensity: 0.45,
        }),
      );
      group.add(body);
    } else {
      body = new THREE.Mesh(
        new THREE.TetrahedronGeometry(typeKey === 'flicker' ? 0.42 : 0.5, 0),
        new THREE.MeshStandardMaterial({
          color: def.color,
          emissive: def.color,
          emissiveIntensity: 0.4,
          metalness: 0.25,
          roughness: 0.4,
        }),
      );
      group.add(body);
    }

    group.position.set(x, def.radius, z);
    this.scene.add(group);

    const e = {
      type: typeKey,
      def,
      mesh: group,
      pos: new THREE.Vector3(x, def.radius, z),
      vel: new THREE.Vector3(),
      hp: def.hp * scale * (typeKey === 'boss' ? 1 + (this.run.floor - 1) * 0.25 : 1),
      maxHp: def.hp * scale * (typeKey === 'boss' ? 1 + (this.run.floor - 1) * 0.25 : 1),
      radius: def.radius,
      flash: 0,
      cd: rand(this.rng, 0, 0.8),
      phase: this.rng() * Math.PI * 2,
      dead: false,
      armor: def.armor || 0,
      hitPulse: 0,
    };
    this.enemies.push(e);
    return e;
  }

  _updateAim() {
    this.raycaster.setFromCamera(this.pointerNdc, this.camera);
    const hit = new THREE.Vector3();
    if (this.raycaster.ray.intersectPlane(this.groundPlane, hit)) {
      aimFlat(this.player.pos, hit, this.aim);
      this.player.facing.copy(this.aim);
    }
  }

  start() {
    this.clock.start();
    const loop = () => {
      requestAnimationFrame(loop);
      const rawDt = Math.min(0.033, this.clock.getDelta());
      this._frame(rawDt);
    };
    loop();
  }

  _frame(rawDt) {
    let dt = rawDt;
    if (this.hitstop > 0) {
      this.hitstop -= rawDt;
      dt *= 0.15;
    }
    this.elapsed += rawDt;

    if (this.state === 'playing') {
      this.run.time += rawDt;
      this._updateAim();
      this._updatePlayer(dt);
      this._updateTether(dt);
      this._updateEnemies(dt);
      this._updateProjectiles(dt);
      this._updatePickups(dt);
      this._updatePortal(dt);
      this._checkRoomClear();
    } else if (this.state === 'title' || this.state === 'dead' || this.state === 'win') {
      this._updateAim();
      // idle spin on player
      if (this.player) {
        this.player.ring.rotation.z = this.elapsed * 1.2;
        this.player.core.rotation.y = this.elapsed * 0.8;
      }
    }

    this.particles.update(dt);
    this._updateCamera(dt);
    this._updateTetherVisual();
    this._animateMeshes(dt);
    this.ui.updateHud(this);
    this.renderer.render(this.scene, this.camera);

    this.mouse.lmbPressed = false;
    this.mouse.rmbPressed = false;
  }

  _animateMeshes(dt) {
    const p = this.player;
    p.ring.rotation.z += dt * 2.5;
    p.core.rotation.y += dt * 1.8;
    p.shell.rotation.y -= dt * 1.1;
    const pulse = 1 + Math.sin(this.elapsed * 6) * 0.04 + (p.dashing ? 0.15 : 0);
    p.core.scale.setScalar(pulse);
    p.light.intensity = 1.2 + Math.sin(this.elapsed * 8) * 0.25 + this.stats.heat / 100;

    if (p.pulseFlash > 0) {
      p.pulseFlash -= dt;
      p.shell.material.opacity = 0.35 + p.pulseFlash * 0.8;
    }

    for (const e of this.enemies) {
      if (e.dead) continue;
      e.mesh.rotation.y += dt * (e.type === 'boss' ? 0.6 : 1.5);
      if (e.flash > 0) {
        e.flash -= dt;
        e.mesh.traverse((c) => {
          if (c.isMesh && c.material && c.material.emissive) {
            c.material.emissiveIntensity = 0.4 + e.flash * 4;
          }
        });
      }
      if (e.type === 'boss' && e.mesh.userData.halo) {
        e.mesh.userData.halo.rotation.z += dt * 1.5;
      }
    }
  }

  _updateCamera(dt) {
    const target = TMP.v.set(this.player.pos.x, 0, this.player.pos.z);
    this.camTarget.lerp(target, 1 - Math.pow(0.001, dt));

    const camDist = this.run.isBoss ? 26 : 22;
    const camZ = this.run.isBoss ? 18 : 15;
    const desired = TMP.v2.set(this.camTarget.x, camDist * 0.95, this.camTarget.z + camZ);

    if (this.camShake > 0) {
      this.camShake = Math.max(0, this.camShake - dt * 4);
      desired.x += (Math.random() - 0.5) * this.camShake * 0.6;
      desired.y += (Math.random() - 0.5) * this.camShake * 0.3;
      desired.z += (Math.random() - 0.5) * this.camShake * 0.6;
    }

    this.camera.position.lerp(desired, 1 - Math.pow(0.0008, dt));
    this.camera.lookAt(this.camTarget.x, 0.2, this.camTarget.z);
  }

  _updatePlayer(dt) {
    const s = this.stats;
    const p = this.player;

    if (s.invuln > 0) s.invuln -= dt;

    // heat decay
    if (s.heat > 0) s.heat = Math.max(0, s.heat - s.heatDecay * dt);

    // movement
    let mx = 0;
    let mz = 0;
    if (this.keys.has('w') || this.keys.has('arrowup')) mz -= 1;
    if (this.keys.has('s') || this.keys.has('arrowdown')) mz += 1;
    if (this.keys.has('a') || this.keys.has('arrowleft')) mx -= 1;
    if (this.keys.has('d') || this.keys.has('arrowright')) mx += 1;

    if (p.dashCd > 0) p.dashCd -= dt;
    if (p.dashes < s.dashCharges && p.dashCd <= 0) {
      p.dashes += 1;
      if (p.dashes < s.dashCharges) p.dashCd = s.dashCooldown * s.dashCdMul;
    }

    if (p.dashing) {
      p.dashTimer -= dt;
      if (s.dashTrail) {
        this._lineHurt(p.pos.x, p.pos.z, p.pos.x + p.vel.x * dt, p.pos.z + p.vel.z * dt, 12 * dt, 0.5, 'dash');
        this.particles.spawn(p.pos.x, 0.4, p.pos.z, {
          color: COLORS.orange,
          speed: 2,
          life: 0.25,
          size: 0.15,
        });
      }
      if (p.dashTimer <= 0) p.dashing = false;
    } else {
      const len = Math.hypot(mx, mz) || 1;
      const ax = (mx / len) * s.moveSpeed;
      const az = (mz / len) * s.moveSpeed;
      if (mx || mz) {
        p.vel.x = THREE.MathUtils.lerp(p.vel.x, ax, 1 - Math.pow(0.0002, dt));
        p.vel.z = THREE.MathUtils.lerp(p.vel.z, az, 1 - Math.pow(0.0002, dt));
      } else {
        p.vel.x *= Math.pow(0.02, dt);
        p.vel.z *= Math.pow(0.02, dt);
      }

      // dash
      if ((this.keys.has(' ') || this.keys.has('shift')) && p.dashes > 0) {
        // only trigger once per press roughly
        if (!p._dashLatch) {
          p._dashLatch = true;
          const dir = TMP.v.set(mx, 0, mz);
          if (dir.lengthSq() < 0.01) dir.copy(this.aim);
          dir.normalize();
          p.vel.copy(dir.multiplyScalar(s.dashSpeed));
          p.dashing = true;
          p.dashTimer = s.dashDuration;
          p.dashes -= 1;
          p.dashCd = s.dashCooldown * s.dashCdMul;
          s.invuln = Math.max(s.invuln, s.dashDuration + 0.05);
          this.audio.dash();
          this.particles.burst(p.pos.x, 0.4, p.pos.z, 14, {
            color: COLORS.cyan,
            speed: 6,
            life: 0.3,
          });
          this.camShake = Math.max(this.camShake, 0.35);
        }
      } else {
        p._dashLatch = false;
      }
    }

    // pulse overload
    if ((this.keys.has('q') || this.keys.has('f')) && !p._pulseLatch) {
      p._pulseLatch = true;
      this._tryPulse();
    } else if (!this.keys.has('q') && !this.keys.has('f')) {
      p._pulseLatch = false;
    }

    p.pos.x += p.vel.x * dt;
    p.pos.z += p.vel.z * dt;
    this._clampEntity(p.pos, p.radius);
    this._resolveObstacles(p.pos, p.radius);
    p.group.position.copy(p.pos);

    // contact damage from enemies
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist2(p.pos.x, p.pos.z, e.pos.x, e.pos.z);
      if (d < p.radius + e.radius * 0.85) {
        this._hurtPlayer(e.def.contact * dt * 2.2, e.pos);
        // soft separate
        const nx = (p.pos.x - e.pos.x) / (d || 1);
        const nz = (p.pos.z - e.pos.z) / (d || 1);
        p.vel.x += nx * 8 * dt;
        p.vel.z += nz * 8 * dt;
      }
    }
  }

  _tryPulse() {
    const s = this.stats;
    if (s.heat < s.pulseCost) {
      this.ui.toast('Need more heat');
      return;
    }
    s.heat -= s.pulseCost;
    this.player.pulseFlash = 0.35;
    this.audio.pulse();
    this.camShake = Math.max(this.camShake, 1.1);
    this.hitstop = 0.06;
    this.particles.ring(this.player.pos.x, 0.5, this.player.pos.z, 36, s.pulseRadius, {
      color: COLORS.orange,
      speed: 12,
      life: 0.45,
    });
    this.particles.burst(this.player.pos.x, 0.5, this.player.pos.z, 28, {
      color: COLORS.gold,
      speed: 8,
      life: 0.4,
    });

    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist2(this.player.pos.x, this.player.pos.z, e.pos.x, e.pos.z);
      if (d < s.pulseRadius + e.radius) {
        const falloff = 1 - d / (s.pulseRadius + e.radius);
        this._damageEnemy(e, s.pulseDamage * (0.55 + 0.45 * falloff), true);
        const nx = (e.pos.x - this.player.pos.x) / (d || 1);
        const nz = (e.pos.z - this.player.pos.z) / (d || 1);
        e.vel.x += nx * s.pulseKnock * falloff;
        e.vel.z += nz * s.pulseKnock * falloff;
      }
    }
    // clear nearby projectiles
    this.projectiles = this.projectiles.filter((pr) => {
      const d = dist2(this.player.pos.x, this.player.pos.z, pr.pos.x, pr.pos.z);
      if (d < s.pulseRadius) {
        this.scene.remove(pr.mesh);
        return false;
      }
      return true;
    });
  }

  _updateTether(dt) {
    const t = this.tetherLine;
    const s = this.stats;
    const p = this.player;
    t.prevTip.copy(t.tipPos);

    // start throw
    if (this.mouse.lmbPressed && (t.state === 'idle' || t.state === 'returning')) {
      this._throwTether();
    }

    // hold LMB while thrown for orbit spin if unlocked
    if (s.orbitSpin && this.mouse.lmb && (t.state === 'thrown' || t.state === 'orbit')) {
      if (t.state === 'thrown' && t.throwAge > 0.08) t.state = 'orbit';
    }

    // RMB reel
    const reeling = this.mouse.rmb;

    if (t.state === 'idle') {
      // tip rests near player in aim direction
      const rest = TMP.v.copy(this.aim).multiplyScalar(0.75).add(p.pos);
      rest.y = 0.55;
      t.tipPos.lerp(rest, 1 - Math.pow(0.0001, dt));
      t.tipVel.set(0, 0, 0);
    } else if (t.state === 'orbit') {
      t.spinAngle += dt * 10 * s.orbitDpsMul;
      const r = s.tetherRange * 0.72;
      t.tipPos.x = p.pos.x + Math.cos(t.spinAngle) * r;
      t.tipPos.z = p.pos.z + Math.sin(t.spinAngle) * r;
      t.tipPos.y = 0.55;
      // damage along sweep
      this._tipContactDamage(dt, s.tipDamage * 0.85 * s.orbitDpsMul);
      this._lineSweepDamage(dt);
      if (!this.mouse.lmb) {
        // fling outward
        t.state = 'thrown';
        t.tipVel.set(-Math.sin(t.spinAngle), 0, Math.cos(t.spinAngle)).multiplyScalar(s.tipSpeed * 0.9);
        t.bouncesLeft = s.tipBounces;
      }
    } else if (t.state === 'thrown') {
      t.throwAge += dt;

      // homing
      if (s.homing > 0) {
        let best = null;
        let bestD = 4.5 + s.homing * 1.5;
        for (const e of this.enemies) {
          if (e.dead) continue;
          const d = dist2(t.tipPos.x, t.tipPos.z, e.pos.x, e.pos.z);
          if (d < bestD) {
            bestD = d;
            best = e;
          }
        }
        if (best) {
          const dir = aimFlat(t.tipPos, best.pos, TMP.v);
          t.tipVel.x += dir.x * s.homing * 40 * dt;
          t.tipVel.z += dir.z * s.homing * 40 * dt;
        }
      }

      t.tipPos.x += t.tipVel.x * dt;
      t.tipPos.z += t.tipVel.z * dt;
      t.tipPos.y = 0.55;

      // spring constraint beyond range
      const dx = t.tipPos.x - p.pos.x;
      const dz = t.tipPos.z - p.pos.z;
      const dist = Math.hypot(dx, dz);
      if (dist > s.tetherRange) {
        const nx = dx / dist;
        const nz = dz / dist;
        t.tipPos.x = p.pos.x + nx * s.tetherRange;
        t.tipPos.z = p.pos.z + nz * s.tetherRange;
        // kill outward velocity
        const vn = t.tipVel.x * nx + t.tipVel.z * nz;
        if (vn > 0) {
          t.tipVel.x -= vn * nx * 1.4;
          t.tipVel.z -= vn * nz * 1.4;
        }
        if (!reeling) {
          // auto-return when stretched and slowing
          if (t.throwAge > 0.2 && t.tipVel.length() < 6) t.state = 'returning';
        }
      }

      // wall bounce / latch
      this._tetherWorldCollide(t, s);

      // enemy latch / hit
      this._tipContactDamage(dt, s.tipDamage);
      this._tryLatchEnemy(t);

      // reel pulls tip back faster
      if (reeling) {
        const dir = aimFlat(t.tipPos, p.pos, TMP.v);
        t.tipVel.x += dir.x * s.reelSpeed * 2.2 * dt;
        t.tipVel.z += dir.z * s.reelSpeed * 2.2 * dt;
      }

      // drag
      t.tipVel.x *= Math.pow(0.12, dt);
      t.tipVel.z *= Math.pow(0.12, dt);

      this._lineSweepDamage(dt);

      // twin tip
      if (t.twin) this._updateTwin(t.twin, dt);

      // auto return timeout
      if (t.throwAge > 1.6) t.state = 'returning';

      // second click returns
      if (this.mouse.lmbPressed && t.throwAge > 0.1) t.state = 'returning';
    } else if (t.state === 'latched') {
      if (t.latchKind === 'enemy' && t.latchTarget && !t.latchTarget.dead) {
        const e = t.latchTarget;
        t.tipPos.copy(e.pos);
        t.tipPos.y = 0.55;
        // pull enemy toward player when reeling
        if (reeling) {
          const dir = aimFlat(e.pos, p.pos, TMP.v);
          e.vel.x += dir.x * s.reelSpeed * 1.6 * dt;
          e.vel.z += dir.z * s.reelSpeed * 1.6 * dt;
          // pull player slightly toward enemy for skill expression
          p.vel.x += dir.x * -3.5 * dt;
          p.vel.z += dir.z * -3.5 * dt;
        } else if (s.wallSling) {
          // mild pull on player for tension
          const dir = aimFlat(p.pos, e.pos, TMP.v);
          const d = dist2(p.pos.x, p.pos.z, e.pos.x, e.pos.z);
          if (d > 2) {
            p.vel.x += dir.x * 2.5 * dt;
            p.vel.z += dir.z * 2.5 * dt;
          }
        }
        // latch DPS
        this._damageEnemy(e, s.latchDps * dt, false, true);
        if (s.lifesteal > 0) {
          s.hp = Math.min(s.maxHp, s.hp + s.latchDps * dt * s.lifesteal);
        }
        this.particles.spawn(e.pos.x, 0.6, e.pos.z, {
          color: COLORS.cyan,
          speed: 1.5,
          life: 0.2,
          size: 0.1,
        });
        this._lineSweepDamage(dt * 0.5);
      } else if (t.latchKind === 'wall' || t.latchKind === 'obstacle') {
        // fixed latch point
        if (reeling || this.mouse.lmbPressed) {
          // slingshot player toward latch
          const dir = aimFlat(p.pos, t.tipPos, TMP.v);
          const power = 22 * (s.slingPower || 1);
          p.vel.x += dir.x * power * dt * (reeling ? 2.4 : 1);
          p.vel.z += dir.z * power * dt * (reeling ? 2.4 : 1);
          if (s.wallSling && this.mouse.lmbPressed) {
            p.vel.x = dir.x * 20 * s.slingPower;
            p.vel.z = dir.z * 20 * s.slingPower;
            this._breakLatch(true);
            this.particles.burst(p.pos.x, 0.5, p.pos.z, 12, { color: COLORS.gold, speed: 7 });
            this.audio.dash();
          }
        }
        // stretch limit breaks latch
        const d = dist2(p.pos.x, p.pos.z, t.tipPos.x, t.tipPos.z);
        if (d > s.tetherRange * 1.05) this._breakLatch(true);
      } else {
        this._breakLatch(false);
      }

      // release latch on second LMB without wall sling
      if (this.mouse.lmbPressed && t.state === 'latched' && t.latchKind === 'enemy') {
        this._flingLatched();
      }
    } else if (t.state === 'returning') {
      const dir = aimFlat(t.tipPos, p.pos, TMP.v);
      const spd = s.returnSpeed * (reeling ? 1.4 : 1);
      t.tipVel.x = dir.x * spd;
      t.tipVel.z = dir.z * spd;
      t.tipPos.x += t.tipVel.x * dt;
      t.tipPos.z += t.tipVel.z * dt;
      t.tipPos.y = 0.55;
      this._tipContactDamage(dt, s.tipDamage * 0.7);
      this._lineSweepDamage(dt);
      if (t.twin) this._updateTwin(t.twin, dt);
      if (dist2(t.tipPos.x, t.tipPos.z, p.pos.x, p.pos.z) < 0.7) {
        t.state = 'idle';
        t.twin = null;
        this.twinVisual.tip.visible = false;
      }
    }
  }

  _throwTether() {
    const t = this.tetherLine;
    const s = this.stats;
    t.state = 'thrown';
    t.throwAge = 0;
    t.latchTarget = null;
    t.latchKind = null;
    t.bouncesLeft = s.tipBounces;
    t.tipPos.copy(this.player.pos).addScaledVector(this.aim, 0.8);
    t.tipPos.y = 0.55;
    t.tipVel.copy(this.aim).multiplyScalar(s.tipSpeed);
    // add player velocity
    t.tipVel.x += this.player.vel.x * 0.35;
    t.tipVel.z += this.player.vel.z * 0.35;
    t.damageCd.clear();
    this.audio.throwTip();
    this.particles.burst(t.tipPos.x, 0.5, t.tipPos.z, 8, {
      color: COLORS.cyan,
      speed: 5,
      life: 0.25,
    });

    if (s.twinTip) {
      const side = TMP.v2.set(-this.aim.z, 0, this.aim.x);
      t.twin = {
        pos: t.tipPos.clone().addScaledVector(side, 0.6),
        vel: this.aim.clone().multiplyScalar(s.tipSpeed * 0.85).addScaledVector(side, 6),
        age: 0,
        alive: true,
      };
      this.twinVisual.tip.visible = true;
    } else {
      t.twin = null;
      this.twinVisual.tip.visible = false;
    }
  }

  _updateTwin(twin, dt) {
    if (!twin.alive) return;
    const s = this.stats;
    twin.age += dt;
    twin.pos.x += twin.vel.x * dt;
    twin.pos.z += twin.vel.z * dt;
    twin.vel.x *= Math.pow(0.15, dt);
    twin.vel.z *= Math.pow(0.15, dt);

    // pull back eventually
    if (twin.age > 0.55) {
      const dir = aimFlat(twin.pos, this.player.pos, TMP.v);
      twin.vel.x += dir.x * s.returnSpeed * 1.2 * dt;
      twin.vel.z += dir.z * s.returnSpeed * 1.2 * dt;
    }

    for (const e of this.enemies) {
      if (e.dead) continue;
      if (dist2(twin.pos.x, twin.pos.z, e.pos.x, e.pos.z) < e.radius + s.tipRadius) {
        this._damageEnemy(e, s.tipDamage * 0.65);
      }
    }

    this.twinVisual.tip.position.set(twin.pos.x, 0.55, twin.pos.z);
    this.twinVisual.tip.rotation.y += dt * 10;

    if (twin.age > 1.8 || dist2(twin.pos.x, twin.pos.z, this.player.pos.x, this.player.pos.z) < 0.6) {
      twin.alive = false;
      this.twinVisual.tip.visible = false;
    }
  }

  _tetherWorldCollide(t, s) {
    const half = this.roomBounds.half - 0.15;
    let bounced = false;
    if (t.tipPos.x > half) {
      t.tipPos.x = half;
      t.tipVel.x *= -0.85;
      bounced = true;
    } else if (t.tipPos.x < -half) {
      t.tipPos.x = -half;
      t.tipVel.x *= -0.85;
      bounced = true;
    }
    if (t.tipPos.z > half) {
      t.tipPos.z = half;
      t.tipVel.z *= -0.85;
      bounced = true;
    } else if (t.tipPos.z < -half) {
      t.tipPos.z = -half;
      t.tipVel.z *= -0.85;
      bounced = true;
    }

    for (const o of this.obstacles) {
      const d = dist2(t.tipPos.x, t.tipPos.z, o.x, o.z);
      if (d < o.radius + s.tipRadius) {
        const nx = (t.tipPos.x - o.x) / (d || 1);
        const nz = (t.tipPos.z - o.z) / (d || 1);
        t.tipPos.x = o.x + nx * (o.radius + s.tipRadius + 0.01);
        t.tipPos.z = o.z + nz * (o.radius + s.tipRadius + 0.01);
        const vn = t.tipVel.x * nx + t.tipVel.z * nz;
        t.tipVel.x -= 1.7 * vn * nx;
        t.tipVel.z -= 1.7 * vn * nz;
        bounced = true;
        // chance to latch solid if slow
        if (s.wallSling && t.tipVel.length() < 10) {
          t.state = 'latched';
          t.latchKind = 'obstacle';
          t.latchTarget = o;
          this.audio.latch();
        }
      }
    }

    if (bounced) {
      if (t.bouncesLeft > 0) {
        t.bouncesLeft -= 1;
        // refresh damage cds for bounce hits
        t.damageCd.clear();
        this.particles.burst(t.tipPos.x, 0.5, t.tipPos.z, 6, { color: COLORS.white, speed: 4, life: 0.2 });
      } else if (!s.wallSling) {
        // sticky latch on walls when no bounces and holding RMB
        if (this.mouse.rmb && t.tipVel.length() < 14) {
          t.state = 'latched';
          t.latchKind = 'wall';
          t.latchTarget = null;
          this.audio.latch();
        }
      } else if (this.mouse.rmb) {
        t.state = 'latched';
        t.latchKind = 'wall';
        t.latchTarget = null;
        this.audio.latch();
      }
    }
  }

  _tryLatchEnemy(t) {
    const s = this.stats;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist2(t.tipPos.x, t.tipPos.z, e.pos.x, e.pos.z);
      if (d < e.radius + s.tipRadius * 1.1) {
        // latch if tip relatively slow or player holding RMB
        if (this.mouse.rmb || t.tipVel.length() < 16 || e.type === 'bulwark' || e.type === 'boss') {
          t.state = 'latched';
          t.latchKind = 'enemy';
          t.latchTarget = e;
          this.audio.latch();
          this.particles.burst(e.pos.x, 0.6, e.pos.z, 10, { color: COLORS.cyan, speed: 5 });
          this.camShake = Math.max(this.camShake, 0.25);
          return;
        }
      }
    }
  }

  _flingLatched() {
    const t = this.tetherLine;
    const s = this.stats;
    if (t.latchKind === 'enemy' && t.latchTarget && !t.latchTarget.dead) {
      const e = t.latchTarget;
      const dir = aimFlat(this.player.pos, e.pos, TMP.v);
      e.vel.x += dir.x * 22;
      e.vel.z += dir.z * 22;
      this._damageEnemy(e, s.tipDamage * 1.3, true);
      if (s.snapBurst > 0) this._snapBurst(e.pos, 22 * s.snapBurst);
    }
    this._breakLatch(true);
  }

  _breakLatch(snap) {
    const t = this.tetherLine;
    if (snap && t.latchKind === 'enemy' && t.latchTarget && this.stats.snapBurst > 0) {
      this._snapBurst(t.tipPos, 18 * this.stats.snapBurst);
    }
    t.latchTarget = null;
    t.latchKind = null;
    t.state = 'returning';
  }

  _snapBurst(pos, dmg) {
    this.particles.ring(pos.x, 0.5, pos.z, 16, 2.2, { color: COLORS.violet, speed: 9, life: 0.3 });
    this.audio.hit(true);
    for (const e of this.enemies) {
      if (e.dead) continue;
      if (dist2(pos.x, pos.z, e.pos.x, e.pos.z) < 2.6 + e.radius) {
        this._damageEnemy(e, dmg, true);
      }
    }
  }

  _tipContactDamage(dt, baseDamage) {
    const t = this.tetherLine;
    const s = this.stats;
    const speed = t.tipVel.length();
    const speedMul = 0.65 + clamp(speed / 30, 0, 1.2);

    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist2(t.tipPos.x, t.tipPos.z, e.pos.x, e.pos.z);
      if (d < e.radius + s.tipRadius) {
        const key = e;
        const cd = t.damageCd.get(key) || 0;
        if (cd > 0) {
          t.damageCd.set(key, cd - dt);
          continue;
        }
        t.damageCd.set(key, 0.12);
        let dmg = baseDamage * speedMul * (s.bounceDamageMul || 1);
        const crit = this.rng() < s.critChance;
        if (crit) dmg *= s.critMul;
        this._damageEnemy(e, dmg, crit);
        // knock
        const nx = (e.pos.x - t.tipPos.x) / (d || 1);
        const nz = (e.pos.z - t.tipPos.z) / (d || 1);
        e.vel.x += nx * 6 + t.tipVel.x * 0.08;
        e.vel.z += nz * 6 + t.tipVel.z * 0.08;
        s.heat = Math.min(s.maxHeat, s.heat + s.heatOnHit * s.heatGain);
        if (s.lifesteal > 0) s.hp = Math.min(s.maxHp, s.hp + dmg * s.lifesteal * 0.35);
      }
    }
  }

  _lineSweepDamage(dt) {
    const t = this.tetherLine;
    const s = this.stats;
    if (s.lineDamage <= 0) return;
    const ax = this.player.pos.x;
    const az = this.player.pos.z;
    const bx = t.tipPos.x;
    const bz = t.tipPos.z;
    this._lineHurt(ax, az, bx, bz, s.lineDamage * dt, s.lineRadius, 'line');
  }

  _lineHurt(ax, az, bx, bz, dmg, radius, tag) {
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = segPointDist(ax, az, bx, bz, e.pos.x, e.pos.z);
      if (d < e.radius + radius) {
        this._damageEnemy(e, dmg, false);
      }
    }
  }

  _updateTetherVisual() {
    const t = this.tetherLine;
    const p = this.player.pos;
    t.tip.position.copy(t.tipPos);
    t.tip.rotation.x += 0.1;
    t.tip.rotation.y += 0.15;

    // color by state
    if (t.state === 'latched') {
      t.mat.color.set(0xff6b2c);
      t.tip.material.emissive.set(0xff6b2c);
    } else if (t.state === 'orbit') {
      t.mat.color.set(0xffd166);
      t.tip.material.emissive.set(0xffd166);
    } else {
      t.mat.color.set(0x4de1ff);
      t.tip.material.emissive.set(0x4de1ff);
    }

    // rope segments with slight sag / wave
    const segs = t.maxSeg;
    const dx = t.tipPos.x - p.x;
    const dz = t.tipPos.z - p.z;
    for (let i = 0; i < segs; i++) {
      const u = i / (segs - 1);
      const x = p.x + dx * u;
      const z = p.z + dz * u;
      const sag = Math.sin(u * Math.PI) * 0.15;
      const wave = Math.sin(u * 10 - this.elapsed * 16) * 0.04 * (t.state === 'idle' ? 0.3 : 1);
      t.positions[i * 3] = x + wave * (t.state === 'orbit' ? 2 : 1);
      t.positions[i * 3 + 1] = 0.55 - sag + wave;
      t.positions[i * 3 + 2] = z;
    }
    t.geo.setDrawRange(0, segs);
    t.geo.attributes.position.needsUpdate = true;
    t.tip.visible = t.state !== 'idle' || true;

    // idle: dim tip
    t.tip.scale.setScalar(t.state === 'idle' ? 0.65 : 1);
  }

  _updateEnemies(dt) {
    const p = this.player.pos;
    for (const e of this.enemies) {
      if (e.dead) continue;
      e.cd -= dt;
      e.phase += dt;

      const dx = p.x - e.pos.x;
      const dz = p.z - e.pos.z;
      const dist = Math.hypot(dx, dz) || 1;
      const nx = dx / dist;
      const nz = dz / dist;

      // friction
      e.vel.x *= Math.pow(0.04, dt);
      e.vel.z *= Math.pow(0.04, dt);

      switch (e.def.kind) {
        case 'melee': {
          e.vel.x += nx * e.def.speed * 3.5 * dt;
          e.vel.z += nz * e.def.speed * 3.5 * dt;
          break;
        }
        case 'ranged': {
          const ideal = e.def.range * 0.65;
          if (dist > ideal + 1) {
            e.vel.x += nx * e.def.speed * 3 * dt;
            e.vel.z += nz * e.def.speed * 3 * dt;
          } else if (dist < ideal - 1.5) {
            e.vel.x -= nx * e.def.speed * 3 * dt;
            e.vel.z -= nz * e.def.speed * 3 * dt;
          } else {
            // strafe
            e.vel.x += -nz * e.def.speed * 2.2 * dt;
            e.vel.z += nx * e.def.speed * 2.2 * dt;
          }
          if (e.cd <= 0 && dist < e.def.range) {
            e.cd = e.def.fireCd * (0.85 + this.rng() * 0.3);
            this._spawnProjectile(e.pos, nx, nz, e.def.projSpeed, e.def.projDamage, 0xc084fc);
          }
          break;
        }
        case 'tank': {
          e.vel.x += nx * e.def.speed * 3 * dt;
          e.vel.z += nz * e.def.speed * 3 * dt;
          break;
        }
        case 'dash': {
          if (e.cd <= 0 && dist < 9) {
            e.cd = e.def.dashCd;
            e.vel.x += nx * 26;
            e.vel.z += nz * 26;
            this.particles.burst(e.pos.x, 0.4, e.pos.z, 6, { color: COLORS.green, speed: 4, life: 0.2 });
          } else {
            e.vel.x += nx * e.def.speed * 2.5 * dt;
            e.vel.z += nz * e.def.speed * 2.5 * dt;
          }
          break;
        }
        case 'orbit': {
          const ox = -nz;
          const oz = nx;
          const pull = dist > 5 ? 1 : dist < 3 ? -1 : 0;
          e.vel.x += (ox * e.def.speed * 3 + nx * pull * e.def.speed) * dt;
          e.vel.z += (oz * e.def.speed * 3 + nz * pull * e.def.speed) * dt;
          break;
        }
        case 'boss': {
          // orbit + charge + spawns
          const orbit = Math.sin(e.phase * 0.7);
          e.vel.x += (nx * 0.6 + -nz * orbit) * e.def.speed * 3 * dt;
          e.vel.z += (nz * 0.6 + nx * orbit) * e.def.speed * 3 * dt;
          if (e.cd <= 0) {
            const pattern = (Math.floor(e.phase) + e.hp) % 3;
            if (pattern === 0) {
              // ring shot
              for (let i = 0; i < 8; i++) {
                const a = (i / 8) * Math.PI * 2 + e.phase;
                this._spawnProjectile(e.pos, Math.cos(a), Math.sin(a), 8, 12, 0xff6b2c);
              }
              e.cd = 1.8;
            } else if (pattern === 1) {
              // charge
              e.vel.x += nx * 30;
              e.vel.z += nz * 30;
              e.cd = 2.2;
              this.camShake = Math.max(this.camShake, 0.5);
            } else {
              // spawn mites
              if (this.enemies.filter((x) => !x.dead).length < 10) {
                for (let i = 0; i < 2; i++) {
                  const a = this.rng() * Math.PI * 2;
                  this._spawnEnemy('mite', e.pos.x + Math.cos(a) * 2.5, e.pos.z + Math.sin(a) * 2.5);
                }
              }
              e.cd = 3.5;
            }
            this.audio.hit(true);
          }
          break;
        }
        default:
          break;
      }

      e.pos.x += e.vel.x * dt;
      e.pos.z += e.vel.z * dt;
      this._clampEntity(e.pos, e.radius);
      this._resolveObstacles(e.pos, e.radius);
      e.mesh.position.copy(e.pos);
      e.mesh.position.y = e.radius + Math.sin(this.elapsed * 3 + e.phase) * 0.05;
    }

    // separate enemies lightly
    for (let i = 0; i < this.enemies.length; i++) {
      const a = this.enemies[i];
      if (a.dead) continue;
      for (let j = i + 1; j < this.enemies.length; j++) {
        const b = this.enemies[j];
        if (b.dead) continue;
        const d = dist2(a.pos.x, a.pos.z, b.pos.x, b.pos.z);
        const min = a.radius + b.radius * 0.9;
        if (d < min && d > 0) {
          const push = (min - d) * 0.5;
          const nx = (a.pos.x - b.pos.x) / d;
          const nz = (a.pos.z - b.pos.z) / d;
          a.pos.x += nx * push;
          a.pos.z += nz * push;
          b.pos.x -= nx * push;
          b.pos.z -= nz * push;
        }
      }
    }
  }

  _spawnProjectile(from, dx, dz, speed, damage, color) {
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(0.16, 8, 8),
      new THREE.MeshStandardMaterial({
        color,
        emissive: color,
        emissiveIntensity: 0.9,
      }),
    );
    mesh.position.set(from.x, 0.55, from.z);
    this.scene.add(mesh);
    this.projectiles.push({
      mesh,
      pos: new THREE.Vector3(from.x, 0.55, from.z),
      vel: new THREE.Vector3(dx * speed, 0, dz * speed),
      damage,
      life: 4,
      radius: 0.18,
    });
  }

  _updateProjectiles(dt) {
    const p = this.player;
    const t = this.tetherLine;
    this.projectiles = this.projectiles.filter((pr) => {
      pr.life -= dt;
      pr.pos.x += pr.vel.x * dt;
      pr.pos.z += pr.vel.z * dt;
      pr.mesh.position.copy(pr.pos);

      // reflect off tether line if tip moving / latched
      if (t.state !== 'idle') {
        const d = segPointDist(p.pos.x, p.pos.z, t.tipPos.x, t.tipPos.z, pr.pos.x, pr.pos.z);
        if (d < 0.35) {
          // bounce away from line midpoint
          pr.vel.x *= -1;
          pr.vel.z *= -1;
          pr.pos.x += pr.vel.x * dt * 2;
          pr.pos.z += pr.vel.z * dt * 2;
          this.particles.spawn(pr.pos.x, 0.5, pr.pos.z, { color: COLORS.cyan, speed: 3, life: 0.2 });
          this.stats.heat = Math.min(this.stats.maxHeat, this.stats.heat + 3);
        }
      }

      if (dist2(pr.pos.x, pr.pos.z, p.pos.x, p.pos.z) < p.radius + pr.radius) {
        this._hurtPlayer(pr.damage, pr.pos);
        this.scene.remove(pr.mesh);
        return false;
      }

      const half = this.roomBounds.half;
      if (pr.life <= 0 || Math.abs(pr.pos.x) > half + 1 || Math.abs(pr.pos.z) > half + 1) {
        this.scene.remove(pr.mesh);
        return false;
      }
      return true;
    });
  }

  _updatePickups(dt) {
    const p = this.player;
    this.pickups = this.pickups.filter((pk) => {
      pk.age += dt;
      pk.mesh.position.y = 0.45 + Math.sin(pk.age * 4) * 0.1;
      pk.mesh.rotation.y += dt * 3;
      const d = dist2(pk.pos.x, pk.pos.z, p.pos.x, p.pos.z);
      if (d < 1.1) {
        if (pk.kind === 'heal') {
          this.stats.hp = Math.min(this.stats.maxHp, this.stats.hp + pk.value);
          this.ui.toast(`+${pk.value} integrity`);
        } else if (pk.kind === 'heat') {
          this.stats.heat = Math.min(this.stats.maxHeat, this.stats.heat + pk.value);
          this.ui.toast(`+${pk.value} heat`);
        } else if (pk.kind === 'score') {
          this.run.score += pk.value;
          this.ui.toast(`+${pk.value} scrap`);
        }
        this.audio.pickup();
        this.particles.burst(pk.pos.x, 0.5, pk.pos.z, 10, { color: COLORS.gold, speed: 4, life: 0.3 });
        this.scene.remove(pk.mesh);
        return false;
      }
      if (pk.age > 12) {
        this.scene.remove(pk.mesh);
        return false;
      }
      return true;
    });
  }

  _spawnPickup(x, z, kind, value) {
    const color = kind === 'heal' ? 0x5dffb1 : kind === 'heat' ? 0xff6b2c : 0xffd166;
    const mesh = new THREE.Mesh(
      new THREE.OctahedronGeometry(0.28, 0),
      new THREE.MeshStandardMaterial({
        color,
        emissive: color,
        emissiveIntensity: 0.7,
      }),
    );
    mesh.position.set(x, 0.45, z);
    this.scene.add(mesh);
    this.pickups.push({
      mesh,
      pos: new THREE.Vector3(x, 0.45, z),
      kind,
      value,
      age: 0,
    });
  }

  _clampEntity(pos, radius) {
    const h = this.roomBounds.half - radius;
    pos.x = clamp(pos.x, -h, h);
    pos.z = clamp(pos.z, -h, h);
  }

  _resolveObstacles(pos, radius) {
    for (const o of this.obstacles) {
