          <div class="upgrade-sub" id="upgrade-sub">Choose one — it lasts this run</div>
          <div class="upgrade-cards" id="upgrade-cards"></div>
          <div class="run-mods" id="run-mods"></div>
        </div>
      </div>

      <div class="screen interactive" id="screen-end">
        <div class="panel">
          <div class="logo" id="end-logo" style="font-size:40px;letter-spacing:0.14em">CORE STILLED</div>
          <div class="tagline" id="end-tag">Sector purged</div>
          <p class="blurb" id="end-blurb"></p>
          <div class="btn-row">
            <button class="btn hot" id="btn-again">Another Run</button>
            <button class="btn ghost" id="btn-title">Title</button>
          </div>
          <div class="stats-line" id="end-best"></div>
        </div>
      </div>
    `;

    this.els = {
      hud: this.root.querySelector('#hud'),
      hpBar: this.root.querySelector('#hp-bar'),
      hpText: this.root.querySelector('#hp-text'),
      heatBar: this.root.querySelector('#heat-bar'),
      heatText: this.root.querySelector('#heat-text'),
      dashText: this.root.querySelector('#dash-text'),
      roomTitle: this.root.querySelector('#room-title'),
      roomSub: this.root.querySelector('#room-sub'),
      scoreText: this.root.querySelector('#score-text'),
      combo: this.root.querySelector('#combo'),
      toast: this.root.querySelector('#toast'),
      dmgFlash: this.root.querySelector('#dmg-flash'),
      paused: this.root.querySelector('#paused-badge'),
      title: this.root.querySelector('#screen-title'),
      upgrade: this.root.querySelector('#screen-upgrade'),
      end: this.root.querySelector('#screen-end'),
      upgradeCards: this.root.querySelector('#upgrade-cards'),
      upgradeSub: this.root.querySelector('#upgrade-sub'),
      runMods: this.root.querySelector('#run-mods'),
      titleBest: this.root.querySelector('#title-best'),
      endLogo: this.root.querySelector('#end-logo'),
      endTag: this.root.querySelector('#end-tag'),
      endBlurb: this.root.querySelector('#end-blurb'),
      endBest: this.root.querySelector('#end-best'),
      pulseHint: this.root.querySelector('#pulse-hint'),
    };

    this.root.querySelector('#btn-start').addEventListener('click', () => this.game?.startRun());
    this.root.querySelector('#btn-again').addEventListener('click', () => this.game?.startRun());
    this.root.querySelector('#btn-title').addEventListener('click', () => {
      this.game.setState('title');
      this.showTitle(this.game.bestScore);
    });
  }

  bind(game) {
    this.game = game;
  }

  onState(state) {
    this.els.title.classList.toggle('visible', state === 'title');
    this.els.upgrade.classList.toggle('visible', state === 'upgrade');
    this.els.end.classList.toggle('visible', state === 'dead' || state === 'win');
    this.els.hud.classList.toggle('visible', state === 'playing' || state === 'paused' || state === 'upgrade');
    this.els.paused.classList.toggle('show', state === 'paused');
  }

  showTitle(best) {
    this.els.titleBest.textContent = `Best scrap: ${best}`;
    this.onState('title');
  }

  updateRoom(run, isBoss) {
    this.els.roomTitle.textContent = isBoss
      ? `DEPTH ${run.floor} — DYNAMO`
      : `DEPTH ${run.floor}`;
    this.els.roomSub.textContent = isBoss
      ? 'Boss chamber'
      : `Room ${run.room} / ${run.roomsThisFloor}`;
  }

  updateHud(game) {
    if (game.state !== 'playing' && game.state !== 'paused' && game.state !== 'upgrade') return;
    const s = game.stats;
    const p = game.player;
    this.els.hpBar.style.transform = `scaleX(${clamp01(s.hp / s.maxHp)})`;
    this.els.hpText.textContent = `${Math.ceil(s.hp)}/${s.maxHp}`;
    this.els.heatBar.style.transform = `scaleX(${clamp01(s.heat / s.maxHeat)})`;
    this.els.heatText.textContent = `${Math.floor(s.heat)}/${s.maxHeat}`;
    this.els.dashText.textContent = `Dash ${p.dashes}/${s.dashCharges}`;
    this.els.scoreText.textContent = `Scrap ${game.run.score} · Kills ${game.run.kills}`;
    const ready = s.heat >= s.pulseCost;
    this.els.pulseHint.textContent = ready ? 'Q Pulse READY' : `Q Pulse (${Math.ceil(s.pulseCost - s.heat)})`;
    this.els.pulseHint.style.color = ready ? '#ff6b2c' : '';

    if (game.comboTimer > 0) {
      game.comboTimer -= game.clock.getDelta() > 0 ? 0.016 : 0.016;
      // actual decay handled lightly; hide when stale
    }
    if (game.comboTimer <= 0) {
      game.combo = 0;
      this.els.combo.classList.remove('show');
    }
  }

  showCombo(n) {
    if (n < 3) return;
    this.els.combo.textContent = `COMBO x${n}`;
    this.els.combo.classList.add('show');
  }

  toast(msg) {
    this.els.toast.textContent = msg;
    this.els.toast.classList.add('show');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => this.els.toast.classList.remove('show'), 1600);
  }

  damageFlash() {
    this.els.dmgFlash.classList.add('show');
    setTimeout(() => this.els.dmgFlash.classList.remove('show'), 90);
  }

  showUpgrades(list, run, stats) {
    this.els.upgradeSub.textContent = `Depth ${run.floor} · Room ${run.room} — pick a mutation`;
    this.els.upgradeCards.innerHTML = '';
    for (const u of list) {
      const btn = document.createElement('button');
      btn.className = `card rarity-${u.rarity}`;
      btn.innerHTML = `
        <div class="card-rarity">${u.rarity}</div>
        <div class="card-name">${u.name}</div>
        <div class="card-desc">${u.desc}</div>
      `;
      btn.addEventListener('click', () => this.game.chooseUpgrade(u.id));
      this.els.upgradeCards.appendChild(btn);
    }

    // owned chips
    this.els.runMods.innerHTML = '';
    for (const id of stats.owned.slice(-12)) {
      const up = UPGRADES.find((x) => x.id === id);
      if (!up) continue;
      const chip = document.createElement('span');
      chip.className = 'mod-chip';
      chip.textContent = up.name;
      this.els.runMods.appendChild(chip);
    }
    this.onState('upgrade');
  }

  showEnd(won, run, best, stats) {
    this.els.endLogo.textContent = won ? 'REACTOR QUIET' : 'CORE RUPTURE';
    this.els.endTag.textContent = won ? 'All three depths stilled' : 'The generator-city consumes you';
    this.els.endBlurb.innerHTML = `
      Scrap <strong>${run.score}</strong> · Kills <strong>${run.kills}</strong> · Depth <strong>${run.floor}</strong><br/>
      Time ${formatTime(run.time)} · Mutations ${stats.owned.length}
    `;
    this.els.endBest.textContent = `Best scrap: ${best}`;
    this.onState(won ? 'win' : 'dead');
  }
}

function clamp01(v) {
  return Math.max(0, Math.min(1, v));
}

function formatTime(s) {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, '0')}`;
}
