import { chromium } from 'playwright';

const url = 'http://127.0.0.1:8765/benches/corelash/runs/test/app/';
const browser = await chromium.launch({
  headless: true,
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
await page.click('#btn-start');
await page.waitForTimeout(300);

// Drive combat via game API for reliability
const result = await page.evaluate(async () => {
  const g = window.__corelash;
  const log = [];
  // Boost for test pace
  g.stats.tipDamage = 80;
  g.stats.lineDamage = 40;
  g.stats.tetherRange = 14;
  g.stats.maxHp = 200;
  g.stats.hp = 200;

  // Simulate many frames of throwing at enemies
  for (let step = 0; step < 400; step++) {
    if (g.state !== 'playing') {
      log.push(`left playing -> ${g.state} at step ${step}`);
      break;
    }
    // Aim at first enemy
    if (g.enemies.length) {
      const e = g.enemies[0];
      g.aim.set(e.pos.x - g.player.pos.x, 0, e.pos.z - g.player.pos.z).normalize();
      if (g.tetherLine.state === 'idle' || g.tetherLine.state === 'returning') {
        g.mouse.lmbPressed = true;
      }
      // reel sometimes
      g.mouse.rmb = step % 40 > 20;
    }
    // move a bit
    g.keys.add('w');
    g._frame(0.016);
    g.keys.delete('w');
    g.mouse.lmbPressed = false;
  }

  log.push({
    state: g.state,
    enemies: g.enemies.length,
    kills: g.run.kills,
    score: g.run.score,
    hp: g.stats.hp,
    heat: g.stats.heat,
    portal: !!g.portal,
    awaiting: g.run.awaitingPortal,
    room: g.run.room,
  });

  // If portal, walk into it
  if (g.portal) {
    for (let i = 0; i < 120; i++) {
      const p = g.portal.pos;
      g.aim.set(p.x - g.player.pos.x, 0, p.z - g.player.pos.z).normalize();
      g.player.pos.x += Math.sign(p.x - g.player.pos.x) * 0.4;
      g.player.pos.z += Math.sign(p.z - g.player.pos.z) * 0.4;
      g._frame(0.016);
      if (g.state === 'upgrade') break;
    }
    log.push({ afterPortal: g.state, upgrades: g.pendingUpgrades?.map(u => u.id) });
    if (g.state === 'upgrade' && g.pendingUpgrades?.length) {
      g.chooseUpgrade(g.pendingUpgrades[0].id);
      log.push({ afterUpgrade: g.state, room: g.run.room, enemies: g.enemies.length, owned: g.stats.owned });
    }
  }

  return log;
});

console.log(JSON.stringify({ errors, result }, null, 2));
await browser.close();
if (errors.length) process.exit(2);
const last = result[result.length - 1];
if (!last || (last.afterUpgrade !== 'playing' && !result.some(r => r.portal || r.awaiting))) {
  // still ok if we at least killed something
}
const kills = result.find(r => r.kills != null)?.kills ?? 0;
if (kills < 1) {
  console.error('NO_KILLS');
  process.exit(4);
}
console.log('COMBAT_OK kills=' + kills);
EOF
