      if (g.aim.lengthSq() > 0) g.aim.normalize();
      if (g.tetherLine.state === 'idle' || g.tetherLine.state === 'returning') g.mouse.lmbPressed = true;
      g.mouse.rmb = true;
    } else if (g.portal) {
      const p = g.portal.pos;
      g.player.pos.x += Math.sign(p.x - g.player.pos.x) * 0.55;
      g.player.pos.z += Math.sign(p.z - g.player.pos.z) * 0.55;
      g.player.group.position.copy(g.player.pos);
    }
    g._frame(0.016);
    g.mouse.lmbPressed = false;
  }
  log.push({
    state: g.state,
    kills: g.run.kills,
    enemies: g.enemies.length,
    portal: !!g.portal,
    upgrades: g.pendingUpgrades?.length || 0,
    heat: g.stats.heat,
  });
  if (g.state === 'upgrade' && g.pendingUpgrades[0]) {
    g.chooseUpgrade(g.pendingUpgrades[0].id);
    log.push({ after: g.state, room: g.run.room, owned: [...g.stats.owned], enemies: g.enemies.length });
  }
  return log;
});
console.log(JSON.stringify({ errors, result }, null, 2));
await browser.close();
if (errors.length) process.exit(2);
if (!result.some(r => r.state === 'upgrade' || r.after === 'playing')) process.exit(5);
console.log('LOOP_OK');
