import { chromium } from 'playwright';
const url = 'http://127.0.0.1:8765/benches/corelash/runs/test/app/';
const browser = await chromium.launch({
  headless: true,
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto(url, { waitUntil: 'networkidle' });
await page.click('#btn-start');
await page.waitForTimeout(150);

// Pause RAF-driven updates by swapping start loop — just blast damage via API
const result = await page.evaluate(() => {
  const g = window.__corelash;
  // Kill all enemies directly to test clear/portal/upgrade path
  for (const e of [...g.enemies]) g._killEnemy(e, true);
  g._frame(0.016);
  const mid = {
    enemies: g.enemies.length,
    portal: !!g.portal,
    awaiting: g.run.awaitingPortal,
    state: g.state,
  };
  // Enter portal
  if (g.portal) {
    g.player.pos.copy(g.portal.pos);
    g.player.pos.y = 0.5;
    for (let i = 0; i < 10; i++) g._frame(0.016);
  }
  const afterPortal = {
    state: g.state,
    upgrades: (g.pendingUpgrades || []).map((u) => u.id),
  };
  if (g.state === 'upgrade' && g.pendingUpgrades[0]) {
    g.chooseUpgrade(g.pendingUpgrades[0].id);
  }
  return {
    mid,
    afterPortal,
    afterPick: {
      state: g.state,
      room: g.run.room,
      enemies: g.enemies.length,
      owned: [...g.stats.owned],
    },
  };
});

console.log(JSON.stringify({ errors, result }, null, 2));
await browser.close();
if (errors.length) process.exit(2);
if (result.afterPick.state !== 'playing' || result.afterPick.room < 2) process.exit(5);
console.log('LOOP_OK');
